pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response time is under 2000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Response contains a non-empty rooms list", function () {
    const body = pm.response.json();
    pm.expect(body.rooms).to.be.an("array").that.is.not.empty;
});

pm.test("Every room has the expected fields and types", function () {
    pm.response.json().rooms.forEach(function (room) {
        pm.expect(room.roomid).to.be.a("number");
        pm.expect(room.roomName).to.be.a("string");
        pm.expect(room.roomPrice).to.be.a("number").and.to.be.above(0);
        pm.expect(room.type).to.be.a("string");
        pm.expect(room.features).to.be.an("array");
        pm.expect(room.accessible).to.be.a("boolean");
    });
});

pm.test("Existing room lookup returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Server responds with an error status (not 2xx)", function () {
    pm.expect(pm.response.code).to.be.at.least(400);
});

pm.test("Error body is JSON with status, error and path fields", function () {
    const body = pm.response.json();
    pm.expect(body.status).to.eql(pm.response.code);
    pm.expect(body.error).to.be.a("string");
    pm.expect(body.path).to.be.a("string");
});

