});

pm.test("Response contains a non-empty token", function () {
    const body = pm.response.json();
    pm.expect(body.token).to.be.a("string").and.to.not.be.empty;
    pm.collectionVariables.set("token", body.token);
});

pm.test("Status code is 401 Unauthorized", function () {
    pm.response.to.have.status(401);
});

pm.test("Error message is 'Invalid credentials'", function () {
    pm.expect(pm.response.json().error).to.eql("Invalid credentials");
});

pm.test("No token is returned", function () {
    pm.expect(pm.response.json()).to.not.have.property("token");
});

pm.test("Status code is 200 for a valid token", function () {
    pm.response.to.have.status(200);
});

const start = new Date();
start.setDate(start.getDate() + 60 + Math.floor(Math.random() * 600));
const end = new Date(start);
end.setDate(end.getDate() + 2);
pm.collectionVariables.set("checkin", start.toISOString().slice(0, 10));
pm.collectionVariables.set("checkout", end.toISOString().slice(0, 10));

pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

pm.test("Booking echoes the submitted details", function () {
    const body = pm.response.json();
    pm.expect(body.bookingid).to.be.a("number");
    pm.expect(body.roomid).to.eql(1);
    pm.expect(body.firstname).to.eql("Sukanya");
    pm.expect(body.lastname).to.eql("Boopathirajan");
    pm.expect(body.bookingdates.checkin).to.eql(pm.collectionVariables.get("checkin"));
    pm.expect(body.bookingdates.checkout).to.eql(pm.collectionVariables.get("checkout"));
    pm.collectionVariables.set("bookingId", body.bookingid);
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Returns the booking that was just created", function () {
    const body = pm.response.json();
    pm.expect(body.bookingid).to.eql(Number(pm.collectionVariables.get("bookingId")));
    pm.expect(body.roomid).to.eql(1);
    pm.expect(body.firstname).to.eql("Sukanya");
    pm.expect(body.bookingdates.checkin).to.eql(pm.collectionVariables.get("checkin"));
    pm.expect(body.bookingdates.checkout).to.eql(pm.collectionVariables.get("checkout"));
});

pm.test("Status code is 202 Accepted", function () {
    pm.response.to.have.status(202);
});

pm.test("Response body is empty", function () {
    pm.expect(pm.response.text()).to.eql("");
});

pm.test("Deleted booking returns 404 Not Found", function () {
    pm.response.to.have.status(404);
});
